//! Compiles rustdoc into JavaScript that imports bindings.

use crate::codegen::{
    bindings::{self, Printer},
    db::Db,
    rustdoc,
};

/// Compiles a rustdoc module id to JavaScript glue code.
///
/// `src_path` is the path to the source JavaScript file generated by the
/// selected bindings API, such as the `package.js` emitted by wasm-bindgen.
#[salsa::tracked(returns(ref))]
pub fn compile_mod<'db>(
    db: &'db dyn Db,
    api: bindings::Api,
    mod_id: rustdoc::Id<'db>,
    src_path: String,
) -> String {
    let fns = rustdoc::lower_mod_fns(db, mod_id);

    let mut out = Printer::default();

    out.write("import ");
    out.curlies(|out| {
        out.comma_list(fns.iter().map(|fn_| fn_.mangled_name(db)));
    });
    out.write_fmt(format_args!(" from '{}';", src_path));
    out.blank();

    if let Some(init) = api.js_mod_init(&src_path) {
        out.lines(&init);
    }
    out.blank();

    out.write("export ");
    out.curlies(|out| {
        out.comma_list(
            fns.iter()
                .map(|fn_| format!("{} as {}", fn_.mangled_name(db), fn_.name(db))),
        );
    });

    out.into()
}
